ox-shadow:0 0 11px #c8f169;vertical-align:1px;margin-right:8px}.mission-tag span{color:#778178;margin:0 9px}.icon-button{width:39px;height:39px;border:1px solid var(--line);background:rgba(8,15,14,.62);color:var(--cream);font-size:18px;cursor:pointer;transition:.2s}.icon-button:hover{border-color:var(--acid);color:var(--acid)}.screen{position:absolute;inset:0;z-index:8}.title-screen{display:flex;align-items:center;padding:clamp(100px,14vh,150px) 9.5vw 90px;background:linear-gradient(90deg,rgba(6,13,13,.98) 0%,rgba(7,14,14,.91) 36%,rgba(7,14,14,.43) 67%,rgba(7,14,14,.08) 100%),linear-gradient(0deg,rgba(5,10,10,.88),transparent 40%),linear-gradient(180deg,rgba(5,10,10,.4),transparent 26%)}.title-copy{width:min(580px,60vw);position:relative;z-index:1}.eyebrow{font:10px var(--mono);letter-spacing:1.7px;color:var(--acid);text-transform:uppercase}.title-copy h1{font:900 clamp(65px,9vw,124px)/.79 var(--display);letter-spacing:-1.7px;margin:27px 0 20px;text-shadow:0 5px 35px rgba(0,0,0,.4)}.title-copy h1 span{color:var(--acid)}.title-sub{font:11px var(--mono);letter-spacing:2.4px;color:#cbd2c8;margin:0 0 17px}.title-rule{height:1px;width:55px;background:var(--acid);margin:23px 0 16px}.title-desc{font-size:14px;line-height:1.85;color:#bbc2b8;margin:0 0 28px}.title-buttons{display:flex;align-items:center;gap:23px}.primary-button{position:relative;border:0;background:var(--acid);color:#15200f;font:700 12px var(--mono);letter-spacing:1px;padding:16px 21px;min-height:48px;cursor:pointer;transition:transform .18s,background .18s;display:inline-flex;align-items:center;justify-content:space-between;gap:25px}.primary-button:hover{transform:translateY(-2px);background:#d9ff91}.primary-button span{font-size:19px;line-height:12px}.text-button,.secondary-button{padding:10px 0;background:none;border:0;color:#d4d9d0;font:10px var(--mono);letter-spacing:1.2px;cursor:pointer}.text-button span{color:var(--acid);font-size:15px;margin-left:5px}.text-button:hover{color:var(--acid)}.platform-note{font:8px var(--mono);letter-spacing:1.2px;color:#77827a;margin-top:33px}.platform-note span{color:var(--acid);margin:0 7px}.title-side{position:absolute;right:9.5vw;bottom:18%;width:260px;padding:0 0 0 28px;border-left:1px solid rgba(228,237,221,.28);color:#d8ded4}.mission-stamp{display:flex;align-items:center;gap:14px;margin-bottom:39px}.mission-stamp>span{font:900 62px/.8 var(--display);color:var(--acid)}.mission-stamp div{font:9px/1.5 var(--mono);letter-spacing:1px;color:#96a098}.mission-stamp b{font-size:12px;color:#e5e9dd;letter-spacing:1.7px}.briefing-line{font:8px var(--mono);letter-spacing:1.5px;color:#adb8ab;display:flex;align-items:center;gap:10px}.briefing-line i{width:20px;height:1px;background:var(--acid)}.title-side p{font-size:12px;line-height:1.9;color:#b9c2b9;margin:13px 0}.briefing-byline{font:8px var(--mono);letter-spacing:.7px;color:#707c73}.title-footer{position:absolute;bottom:26px;left:4.1vw;right:4.1vw;display:flex;justify-content:space-between;font:8px var(--mono);letter-spacing:1px;color:#748078}.title-footer b{color:var(--acid);margin-left:7px}.hidden{display:none!important}.hud{position:absolute;inset:0;z-index:5;pointer-events:none}.hud button,.mobile-controls{pointer-events:auto}.objective-card{position:absolute;top:104px;left:4.1vw;width:276px;border-left:2px solid var(--acid);padding:10px 14px 12px;background:linear-gradient(90deg,rgba(8,15,14,.74),rgba(8,15,14,.12));backdrop-filter:blur(4px)}.objective-card .eyebrow{font-size:8px;letter-spacing:1.3px}.objective-card .live-dot{width:5px;height:5px}.objective-card>div:nth-child(2){font:600 19px var(--display);letter-spacing:.6px;margin:7px 0 3px}.objective-card>div:nth-child(3){font:9px var(--mono);color:#a7b0a5}.progress-track{height:2px;background:#546052;margin-top:11px}.progress-track span{height:100%;display:block;width:0;background:var(--acid);transition:width .25s}.compass{position:absolute;top:104px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;font:9px var(--mono);color:#e7ecdf;letter-spacing:1px}.compass span:last-child{color:#aab5a8}.compass-line{height:22px;width:3px;background:var(--acid);box-shadow:0 0 9px rgba(200,241,105,.5)}.radio-caption{position:absolute;top:157px;left:4.1vw;font:9px var(--mono);color:#a6afa3;max-width:330px;opacity:0;transform:translateY(4px);transition:.3s}.radio-caption.show{opacity:1;transform:none}.radio-caption>span{color:var(--acid)}.radio-caption b{color:#e8ede1;margin:0 6px}.radio-caption em{display:block;font:italic 11px var(--body);margin-top:5px;color:#d2d7cd}.weapon-readout{position:absolute;bottom:40px;right:4.1vw;text-align:right;padding:0 0 4px 20px;border-left:1px solid rgba(221,230,214,.34)}.weapon-readout>span{display:block;color:#bbc4b6;font:9px var(--mono);letter-spacing:1px;margin-bottom:5px}.weapon-readout strong{font:500 27px var(--display)}.weapon-readout strong small{font:12px var(--mono);color:#97a299}.health-readout{position:absolute;bottom:43px;left:4.1vw;display:flex;align-items:center;gap:9px}.health-icon{color:var(--acid);font:500 24px var(--display);border:1px solid rgba(200,241,105,.5);width:29px;height:29px;display:grid;place-items:center}.health-copy{display:grid;gap:1px}.health-copy span{font:8px var(--mono);color:#abb4a9;letter-spacing:1px}.health-copy strong{font:600 17px var(--display)}.health-bar{width:83px;height:3px;background:rgba(220,225,210,.25);margin-left:4px}.health-bar i{display:block;height:100%;background:var(--acid);width:100%;transition:width .2s,background .2s}.squad-readout{position:absolute;top:102px;right:4.1vw;display:flex;align-items:center;gap:9px;background:rgba(8,14,13,.52);padding:7px 9px}.squad-icon{color:var(--acid);font-size:13px}.squad-readout span:nth-child(2){display:grid;gap:2px}.squad-readout b{font:9px var(--mono);letter-spacing:1px}.squad-readout small{font:7px var(--mono);color:#a0aaa0}.squad-readout>i{width:5px;height:5px;border-radius:50%;background:var(--acid);margin-left:8px}.echo-readout{position:absolute;right:4.1vw;top:155px;display:flex;align-items:center;gap:9px;color:var(--acid);font-size:16px}.echo-readout>div:nth-child(2){display:grid;gap:3px}.echo-readout b{font:8px var(--mono);letter-spacing:1px;color:#dce4d6}.echo-readout small{font:7px var(--mono);color:#a7b39d}.echo-meter{width:47px;height:2px;background:#46513e}.echo-meter i{display:block;width:100%;height:100%;background:var(--acid);transition:width .15s}.scan-banner{position:absolute;top:24%;left:50%;transform:translate(-50%,-10px);font:10px var(--mono);letter-spacing:2px;color:var(--acid);opacity:0;transition:.3s;text-shadow:0 0 12px #9bec5e}.scan-banner.show{opacity:1;transform:translate(-50%,0)}.crosshair{position:absolute;top:50%;left:50%;width:21px;height:21px;transform:translate(-50%,-50%);opacity:.85;transition:transform .1s}.crosshair i{position:absolute;background:rgba(230,239,222,.92);display:block}.crosshair i:nth-child(1){width:1px;height:5px;left:10px;top:0}.crosshair i:nth-child(2){width:1px;height:5px;left:10px;bottom:0}.crosshair i:nth-child(3){height:1px;width:5px;left:0;top:10px}.crosshair i:nth-child(4){height:1px;width:5px;right:0;top:10px}.crosshair b{position:absolute;width:2px;height:2px;background:var(--acid);left:9.5px;top:9.5px}.crosshair.hit{transform:translate(-50%,-50%) scale(1.7);filter:drop-shadow(0 0 4px var(--acid))}.hit-marker{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font:20px var(--display);color:var(--acid);opacity:0;transition:opacity .08s}.hit-marker.show{opacity:1}.center-prompt{position:absolute;top:58%;left:50%;transform:translateX(-50%);font:10px var(--mono);letter-spacing:1px;color:#f1f5e9;background:rgba(7,13,12,.75);padding:9px 13px;border:1px solid rgba(200,241,105,.38);opacity:0;white-space:nowrap;transition:opacity .15s}.center-prompt.show{opacity:1}.desktop-hints{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);font:7px var(--mono);letter-spacing:.9px;color:rgba(220,227,213,.58);white-space:nowrap}.desktop-hints span{color:var(--acid);margin:0 5px}.damage-flash{position:absolute;inset:0;box-shadow:inset 0 0 120px rgba(209,36,26,0);transition:box-shadow .12s}.damage-flash.show{box-shadow:inset 0 0 120px rgba(209,36,26,.7)}.modal-screen{display:grid;place-items:center;background:rgba(3,8,8,.72);backdrop-filter:blur(9px)}.modal-card{width:min(390px,calc(100vw - 42px));padding:36px 39px;background:linear-gradient(145deg,rgba(19,29,25,.98),rgba(7,13,13,.98));border:1px solid rgba(216,232,210,.16);box-shadow:0 30px 90px rgba(0,0,0,.55)}.modal-card h2{font:800 43px/.95 var(--display);letter-spacing:1px;margin:23px 0 8px}.modal-card>p{font-size:12px;color:#aeb8ac;margin:0 0 27px}.modal-card .primary-button{width:100%}.secondary-button{display:block;width:100%;border:1px solid var(--line);margin-top:10px;padding:13px}.modal-card>.text-button{display:block;margin:14px auto 0}.setting-row{display:block;margin:25px 0}.setting-row>span{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:1px;color:#c8d0c3}.setting-row b{color:var(--acid)}input[type=range]{width:100%;accent-color:var(--acid);margin-top:13px}.campaign-screen{background:rgba(3,8,8,.94);backdrop-filter:blur(12px);display:grid;place-items:center;padding:35px}.campaign-shell{width:min(850px,100%);max-height:92vh;overflow:auto;padding:36px 42px;background:linear-gradient(140deg,rgba(18,28,24,.98),rgba(7,13,13,.98));border:1px solid rgba(216,232,210,.16)}.campaign-heading{display:flex;justify-content:space-between;align-items:center}.campaign-heading h2{font:800 44px var(--display);margin:7px 0 0}.campaign-intro{font-size:12px;color:#9eaaa0;margin:13px 0 23px}.mission-list{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.mission-tile{min-height:119px;padding:15px;background:rgba(220,235,215,.035);border:1px solid rgba(220,235,215,.12);position:relative}.mission-tile.active{border-color:rgba(200,241,105,.57);background:rgba(200,241,105,.06)}.mission-tile .num{font:10px var(--mono);color:var(--acid)}.mission-tile h3{font:700 18px var(--display);letter-spacing:.5px;margin:8px 0 3px}.mission-tile p{font-size:9px;color:#98a39a;margin:0}.mission-tile.locked{opacity:.49}.mission-tile.locked:after{content:'LOCKED';position:absolute;right:12px;top:15px;font:7px var(--mono);color:#a9b2a7;letter-spacing:1px}.campaign-bottom{display:flex;justify-content:space-between;align-items:center;margin-top:22px;font:8px var(--mono);letter-spacing:.8px;color:#8f9c91}.campaign-bottom button{padding:12px 17px;min-height:40px}.completion-card{text-align:center}.completion-card .eyebrow{text-align:left}.complete-emblem{width:63px;height:63px;border:1px solid var(--acid);color:var(--acid);display:grid;place-items:center;font:28px var(--display);margin:24px auto 17px;transform:rotate(45deg)}.complete-emblem::first-letter{transform:rotate(-45deg)}.completion-card h2{font-size:39px;margin:0 0 10px}.completion-card>p{margin-bottom:20px}.mission-stats{display:flex;justify-content:center;gap:25px;padding:16px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font:7px var(--mono);letter-spacing:.8px;color:#a8b3a5}.mission-stats span{display:grid;gap:5px}.mission-stats b{font:19px var(--display);color:var(--cream)}.next-mission{display:grid;gap:5px;text-align:left;padding:15px;background:rgba(200,241,105,.05);border-left:2px solid var(--acid);margin:17px 0;font:8px var(--mono);letter-spacing:1px;color:#9eaa9b}.next-mission b{color:var(--cream);font:600 17px var(--display)}.next-mission small{color:var(--acid)}.toast{position:absolute;z-index:20;top:80px;left:50%;transform:translate(-50%,-8px);padding:9px 14px;background:rgba(10,18,16,.91);border:1px solid rgba(200,241,105,.5);font:9px var(--mono);letter-spacing:.7px;color:var(--cream);opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-controls{display:none}.look-zone{position:absolute;right:0;top:22%;bottom:16%;width:55%;pointer-events:auto;touch-action:none}.mo