@media (max-width:800px){.topbar{height:58px;padding:0 18px}.brand{font-size:17px}.brand-mark{width:23px;height:23px}.mission-tag{font-size:8px}.title-screen{padding:100px 8vw 85px;align-items:flex-start;background:linear-gradient(90deg,rgba(6,13,13,.95),rgba(7,14,14,.68) 68%,rgba(7,14,14,.32)),linear-gradient(0deg,rgba(5,10,10,.8),transparent 45%)}.title-copy{width:min(520px,90vw);margin-top:6vh}.title-copy h1{font-size:clamp(74px,17vw,116px);margin:24px 0 19px}.title-side{display:none}.title-footer{left:18px;right:18px;font-size:7px}.title-footer span:first-child{max-width:60%}.title-desc{font-size:13px}.platform-note{font-size:7px}.objective-card{top:73px;left:16px;width:235px;padding:8px 11px}.objective-card>div:nth-child(2){font-size:17px}.objective-card>div:nth-child(3){font-size:8px}.compass{top:77px}.squad-readout{top:72px;right:14px;transform:scale(.88);transform-origin:top right}.echo-readout{top:119px;right:16px;transform:scale(.9);transform-origin:top right}.radio-caption{top:143px;left:16px}.health-readout{bottom:25px;left:17px;transform:scale(.9);transform-origin:bottom left}.weapon-readout{bottom:24px;right:16px}.desktop-hints{display:none}.mobile-controls{display:block}.center-prompt{top:55%}.scan-banner{top:31%}.mission-list{grid-template-columns:repeat(2,1fr)}.campaign-shell{padding:26px 22px}.campaign-screen{padding:15px}.campaign-heading h2{font-size:38px}.campaign-intro{line-height:1.6}.modal-card{padding:30px 27px}.title-sub{font-size:9px;letter-spacing:1.6px}.title-buttons{gap:16px;flex-wrap:wrap}.primary-button{font-size:10px;padding:14px 16px;gap:13px}}
@media (max-height:600px){.title-screen{padding-top:75px;padding-bottom:50px}.title-copy{margin-top:0}.title-copy h1{font-size:68px;margin:17px 0}.title-desc{margin-bottom:16px}.platform-note{margin-top:16px}.title-side{bottom:13%}.objective-card{top:79px}.mobile-controls .move-zone{bottom:4vh;transform:scale(.82);transform-origin:bottom left}.mobile-actions{bottom:3vh;transform:scale(.82);transform-origin:bottom right}.campaign-shell{padding-top:20px;padding-bottom:20px}.mission-tile{min-height:95px}}
@media (pointer:coarse){.mobile-controls{display:block}.desktop-hints{display:none}}

