import * as THREE from 'three';

const $ = (id) => document.getElementById(id);
const ui = Object.fromEntries(['world','hud','screen-title','screen-pause','screen-settings','screen-campaign','screen-complete','objective-title','objective-sub','objective-progress','ammo-now','ammo-reserve','health-value','health-fill','weapon-name','echo-status','echo-fill','scan-banner','center-prompt','damage-flash','hit-marker','radio-caption','compass-degree','toast','sensitivity','sensitivity-value','volume','volume-value'].map(id => [id, $(id)]));
const missions = [
  ['01','BLACKWATER SIGNAL','Coastal relay station · Estonia','active'],
  ['02','GLASS HARBOR','Flooded port · Rotterdam','locked'],
  ['03','RED LINE','Transit hub · Istanbul','locked'],
  ['04','DEAD RECKONING','Mountain pass · Georgia','locked'],
  ['05','GHOST FREQUENCY','Night market · Singapore','locked'],
  ['06','SHADOW PROTOCOL','The source · Classified','locked']
];
$('mission-list').innerHTML = missions.map(([num,name,place,state])=>`<article class="mission-tile ${state}"><span class="num">${num} / 06</span><h3>${name}</h3><p>${place}</p></article>`).join('');

const renderer = new THREE.WebGLRenderer({canvas:ui.world,antialias:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.6));
renderer.setSize(window.innerWidth,window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x172221);
scene.fog = new THREE.FogExp2(0x172221,0.015);
const camera = new THREE.PerspectiveCamera(72,window.innerWidth/window.innerHeight,.08,120);
camera.rotation.order='YXZ';
scene.add(camera);
const clock = new THREE.Clock();
const raycaster = new THREE.Raycaster();
const center = new THREE.Vector2(0,0);
const hemi = new THREE.HemisphereLight(0xb9c9bc,0x26302b,1.42); scene.add(hemi);
const moon = new THREE.DirectionalLight(0xc3d0c8,2.0); moon.position.set(-15,28,12); scene.add(moon);
const fillLight = new THREE.DirectionalLight(0x79918a,.5); fillLight.position.set(17,12,-27); scene.add(fillLight);

const mat=(color,roughness=.85,metalness=0,extra={})=>new THREE.MeshStandardMaterial({color,roughness,metalness,...extra});
const M={ground:mat(0x343936),asphalt:mat(0x272e2c),concrete:mat(0x626963),dark:mat(0x1b2422),metal:mat(0x35413d,.7,.5),rust:mat(0x725743,.8,.25),sand:mat(0x9a8b6c),olive:mat(0x475447),olive2:mat(0x65715b),black:mat(0x151b1a,.45,.5),yellow:mat(0xc7a950),warm:mat(0xffc777,.4,0,{emissive:0xa7591c,emissiveIntensity:1.6}),red:mat(0xff503d,.35,0,{emissive:0x9f100b,emissiveIntensity:1.2}),blue:mat(0x6bb2aa,.5,0,{emissive:0x174d4a,emissiveIntensity:.8})};
const boxGeo=new THREE.BoxGeometry(1,1,1), sphereGeo=new THREE.SphereGeometry(1,12,8), cylGeo=new THREE.CylinderGeometry(.5,.5,1,10);
function addBox(parent,material,pos,size,rotationY=0){const mesh=new THREE.Mesh(boxGeo,material);mesh.position.set(...pos);mesh.scale.set(...size);mesh.rotation.y=rotationY;mesh.castShadow=false;mesh.receiveShadow=false;parent.add(mesh);return mesh;}
function addSphere(parent,material,pos,size){const mesh=new THREE.Mesh(sphereGeo,material);mesh.position.set(...pos);mesh.scale.set(...size);parent.add(mesh);return mesh;}
