  const gun=new THREE.Group();weaponRoot.add(gun);
  addBox(gun,mat(0x252d2a,.42,.55),[.04,-.04,-.38],[.16,.19,.56]);
  addBox(gun,mat(0x424c45,.38,.55),[.035,.035,-.37],[.13,.14,.38]);
