function setScreens({title=false,pause=false,settings=false,campaign=false,complete=false,fail=false}){for(const [id,on]of[['screen-title',title],['screen-pause',pause],['screen-settings',settings],['screen-campaign',campaign],['screen-complete',complete],['screen-fail',fail]])if($(id))$(id).classList.toggle('hidden',!on);}
const raycaster=new THREE.Raycaster();raycaster.far=70;
function aliveCount(){return enemies.filter(e=>e.alive).length;}
function startMission(){gameState='playing';player.pos.set(0,0,15);player.yaw=0;player.pitch=0;player.health=100;player.ammo=30;player.reserve=120;player.reloading=false;player.crouch=false;player.onGround=true;player.velocityY=0;player.echoCooldown=0;player.echoActive=0;player.kills=0;player.objective='clear';player.upload=0;player.startedAt=performance.now();player.win=false;enemies.forEach((e,i)=>{e.alive=true;e.hp=100;e.root.visible=true;e.root.position.set(enemySeeds[i][0],0,enemySeeds[i][1]);e.stun=0;e.lastShot=1+Math.random()*1.7;});buddy.root.visible=true;setScreens({});$('hud').classList.remove('hidden');$('scan-banner').classList.remove('show');ui['objective-title'].textContent='Eliminate hostile forces';radio('Blackwater is ahead. Clear the lane, then secure the relay.');audio();}
function pauseGame(){if(gameState==='playing'){gameState='pause';setScreens({pause:true});document.exitPointerLock?.();}else if(gameState==='pause'){gameState='playing';setScreens({});}}
function setSensitivity(v){sensitivity=Number(v);$('sensitivity-value').textContent=sensitivity.toFixed(1)+'×';}
function doReload(){if(gameState!=='playing'||player.reloading||player.ammo===30||player.reserve<=0)return;player.reloading=true;toast('RELOADING');tone(320,.12,'square',.025,-100);setTimeout(()=>{if(!player.reloading)return;const n=Math.min(30-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;player.reloading=false;ui['ammo-now'].textContent=player.ammo;ui['ammo-reserve'].textContent=player.reserve;tone(520,.07,'square',.025,80);},1150);}
function fire(){if(gameState!=='playing'||player.reloading)return;if(player.ammo<=0){tone(160,.05,'square',.02);toast('MAGAZINE EMPTY · R TO RELOAD');return;}const now=performance.now();if(fire.last&&now-fire.last<135)return;fire.last=now;player.ammo--;ui['ammo-now'].textContent=player.ammo;recoil=Math.min(.09,recoil+.045);weaponRoot.userData.gun.userData.muzzle.intensity=2.2;noise(.075,.17);tone(82,.075,'sawtooth',.045,35);const spread=player.aiming?.002:.014;raycaster.setFromCamera(new THREE.Vector2((Math.random()-.5)*spread,(Math.random()-.5)*spread),camera);const hits=raycaster.intersectObjects(enemies.filter(e=>e.alive).flatMap(e=>e.parts),false);const origin=camera.position.clone(),dir=new THREE.Vector3();camera.getWorldDirection(dir);let end=origin.clone().addScaledVector(dir,48);if(hits.length){const hit=hits[0],e=hit.object.userData.owner;e.hp-=hit.object===e.parts[2]?65:42;e.hitFlash=.14;end.copy(hit.point);ui['hit-marker'].classList.add('show');setTimeout(()=>ui['hit-marker'].classList.remove('show'),100);if(e.hp<=0&&e.alive){e.alive=false;e.root.visible=false;player.kills++;toast('HOSTILE NEUTRALIZED');tone(220,.15,'sine',.04,160);if(!aliveCount()){player.objective='relay';ui['objective-title'].textContent='Secure the relay';ui['objective-sub'].textContent='Reach the marked console · Press E / USE';ui['objective-progress'].style.width='100%';radio('Lane is clear. Move to the relay console and bring it offline.');}}}tracer(origin,end);}
function echoPulse(){if(gameState!=='playing')return;if(player.echoCooldown>0){toast('ECHO RECHARGING');return;}player.echoCooldown=18;player.echoActive=2.8;scanTimer=2.8;for(const e of enemies)if(e.alive)e.stun=3.1;noise(.25,.22);tone(520,.35,'sine',.08,-360);$('scan-banner').classList.add('show');setTimeout(()=>$('scan-banner').classList.remove('show'),2900);toast('ECHO PULSE · HOSTILES DISRUPTED');}
function interact(){if(gameState!=='playing')return;if(player.objective==='relay'){const d=Math.hypot(player.pos.x,player.pos.z+34);if(d<3.2){player.objective='upload';player.upload=0;ui['objective-title'].textContent='Disable the relay';ui['objective-sub'].textContent='Hold position while Vega cuts the signal';radio('I have the console. Cover me while I kill the uplink.');tone(700,.2,'sine',.06,-220);}else toast('MOVE CLOSER TO THE RELAY');}else if(player.objective==='upload')toast('VEGA IS WORKING · HOLD THE AREA');else toast('CLEAR HOSTILES BEFORE APPROACHING THE RELAY');}
function completeMission(){if(player.win)return;player.win=true;gameState='complete';$('stat-kills').textContent=String(player.kills).padStart(2,'0');const sec=Math.floor(player.elapsed),mm=String(Math.floor(sec/60)).padStart(2,'0'),ss=String(sec%60).padStart(2,'0');$('stat-time').textContent=mm+':'+ss;setScreens({complete:true});document.exitPointerLock?.();tone(660,.6,'sine',.07,440);}
function takeDamage(amount){if(gameState!=='playing'||performance.now()-player.lastDamage<430)return;player.lastDamage=performance.now();player.health=Math.max(0,player.health-amount);damageTimer=.35;$('damage-flash').classList.add('active');setTimeout(()=>$('damage-flash').classList.remove('active'),280);ui['health-value'].textContent=player.health;ui['health-fill'].style.width=player.health+'%';tone(95,.14,'sawtooth',.06,-35);if(player.health<=0){gameState='fail';setScreens({fail:true});document.exitPointerLock?.();}}
function clampPlayer(){const r=.32;player.pos.x=THREE.MathUtils.clamp(player.pos.x,-4.25,4.25);player.pos.z=THREE.MathUtils.clamp(player.pos.z,-33,12);for(const b of colliders){const nx=THREE.MathUtils.clamp(player.pos.x,b.x-b.w/2-r,b.x+b.w/2+r),nz=THREE.MathUtils.clamp(player.pos.z,b.z-b.d/2-r,b.z+b.d/2+r);if(Math.abs(player.pos.x-nx)<r&&Math.abs(player.pos.z-nz)<r){const dx=player.pos.x-nx,dz=player.pos.z-nz;if(Math.abs(dx)>Math.abs(dz))player.pos.x=nx+Math.sign(dx||1)*r;else player.pos.z=nz+Math.sign(dz||1)*r;}}}
function updatePlayer(dt){const f=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-touch.moveY,s=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+touch.moveX;const l=Math.hypot(f,s)||1,speed=player.crouch?2.2:4.2,fx=Math.sin(player.yaw),fz=-Math.cos(player.yaw);player.pos.x+=(fx*f+Math.cos(player.yaw)*s)/l*speed*dt;player.pos.z+=(fz*f-Math.sin(player.yaw)*s)/l*speed*dt;clampPlayer();if(!player.onGround){player.velocityY-=17*dt;camera.position.y+=player.velocityY*dt;if(camera.position.y<= (player.crouch?1.12:1.68)){camera.position.y=player.crouch?1.12:1.68;player.onGround=true;player.velocityY=0;}}else camera.position.y+=(player.crouch?1.12:1.68-camera.position.y)*Math.min(1,dt*12);if(f||s)bob+=dt*(player.crouch?7:11);const gun=weaponRoot.userData.gun;gun.position.copy(gun.userData.basePos);gun.position.y+=Math.sin(bob)*.008+(player.aiming?0:-.01);gun.position.x+=Math.cos(bob*.5)*.006;if(player.aiming){gun.position.x*=.28;gun.position.y+=.035;gun.position.z-=.06;}gun.position.y-=recoil;recoil=Math.max(0,recoil-dt*.24);}

