const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--enable-gpu','--ignore-gpu-blocklist','--use-angle=swiftshader']});
 const page=await browser.newPage({viewport:{width:1280,height:720}});
 const errors=[];page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://localhost:3002/',{waitUntil:'networkidle'});
 await page.screenshot({path:'/tmp/opencode/final-title.jpg',type:'jpeg',quality:70});
 await page.locator('#deploy-button').click();
 await page.waitForTimeout(1200);
 const mission={hud:await page.locator('#hud').isVisible(), objective:await page.locator('#objective-title').innerText(), ammo:await page.locator('#ammo-now').innerText(), canvas:await page.locator('#world').evaluate(e=>[e.width,e.height])};
 await page.screenshot({path:'/tmp/opencode/final-gameplay.jpg',type:'jpeg',quality:70});
 await page.keyboard.press('q');
 const echo=await page.locator('#toast').innerText();
 await page.keyboard.press('r');
 await page.waitForTimeout(1250);
 const reload=await page.locator('#ammo-now').innerText();
 await page.locator('#pause-top').click();
 const paused=await page.locator('#screen-pause').isVisible();
 await page.locator('#settings-button').click();
 const settings=await page.locator('#screen-settings').isVisible();
 await page.locator('#sensitivity').fill('1.7');
 const sensitivity=await page.locator('#sensitivity-value').innerText();
 await page.locator('#settings-back').click();
 await page.locator('#resume-button').click();
 const resumed=await page.locator('#screen-pause').isHidden();
 console.log(JSON.stringify({mission,echo,reload,paused,settings,sensitivity,resumed,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

