import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:false, executablePath:'/home/runner/.cache/ms-playwright/chromium-1255/chrome-linux64/chrome', args:['--no-sandbox','--enable-gpu','--ignore-gpu-blocklist','--enable-unsafe-webgpu','--use-angle=vulkan','--enable-features=Vulkan','--use-vulkan=swiftshader','--use-webgpu-adapter=swiftshader','--disable-vulkan-surface']});
const page = await browser.newPage({viewport:{width:390,height:844}, isMobile:true, hasTouch:true, deviceScaleFactor:1});
const errors=[];
page.on('pageerror', e=>errors.push('pageerror: '+e.message));
page.on('console', m=>{if(m.type()==='error')errors.push('console: '+m.text())});
page.on('response', r=>{if(r.status()>=400)errors.push(`HTTP ${r.status()} ${r.url()}`)});
await page.route('**/game.js', async route=>{
 const response=await route.fetch();
 const source=await response.text();
 await route.fulfill({response,body:source+'\nwindow.__test={player,enemies,interact,takeDamage,doReload,echoPulse,get state(){return gameState}};'});
});
await page.goto('http://localhost:3002/',{waitUntil:'networkidle'});
await page.locator('#deploy-button').tap();
await page.waitForSelector('#hud:not(.hidden)');
await page.waitForTimeout(500);
const fire=page.locator('#btn-fire');
for(let i=0;i<5;i++){await fire.tap();await page.waitForTimeout(170);}
const afterFire=await page.locator('#ammo-now').textContent();
await page.locator('#btn-reload').tap();
await page.waitForTimeout(1300);
const afterReload={ammo:await page.locator('#ammo-now').textContent(),reserve:await page.locator('#ammo-reserve').textContent()};
await page.locator('#btn-echo').tap();
const echo=await page.locator('#echo-status').textContent();
const buttonBounds=await page.locator('.mobile-actions .touch-action, .mobile-actions .fire-button').evaluateAll(nodes=>nodes.map(el=>{const r=el.getBoundingClientRect();return {id:el.id,left:Math.round(r.left),right:Math.round(r.right),top:Math.round(r.top),bottom:Math.round(r.bottom),visible:!!(r.width&&r.height)}}));
await page.screenshot({path:'/tmp/opencode/current-gameplay.jpg',type:'jpeg',quality:85});
// Exercise relay activation, mission completion, failure and retry with controlled state fixtures.
await page.evaluate(()=>{for(const e of window.__test.enemies){e.alive=false;e.root.visible=false;}window.__test.player.kills=5;window.__test.player.objective='relay';window.__test.player.pos.set(0,0,-31);});
await page.locator('#btn-use').tap();
const objectiveAfterUse=await page.locator('#objective-title').textContent();
await page.waitForTimeout(5400);
const completed=await page.locator('#screen-complete').evaluate(el=>!el.classList.contains('hidden'));
await page.locator('#complete-menu').tap();
await page.locator('#deploy-button').tap();
await page.evaluate(()=>{window.__test.player.health=8;window.__test.takeDamage(10)});
const failed=await page.locator('#screen-fail').evaluate(el=>!el.classList.contains('hidden'));
await page.locator('#fail-retry').tap();
await page.waitForTimeout(200);
const retry={state:await page.evaluate(()=>window.__test.state),health:await page.locator('#health-value').textContent(),ammo:await page.locator('#ammo-now').textContent(),failScreen:await page.locator('#screen-fail').evaluate(el=>!el.classList.contains('hidden'))};
console.log(JSON.stringify({afterFire,afterReload,echo,buttonBounds,objectiveAfterUse,completed,failed,retry,errors},null,2));
